import{_ as t,o as e,c as n,ae as a}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-09","description":"","frontmatter":{"date":"2026-07-09T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-09-uxtrend.md","filePath":"daily/2026-07-09-uxtrend.md"}'),o={name:"daily/2026-07-09-uxtrend.md"};function s(i,r,g,p,h,l){return e(),n("div",null,[...r[0]||(r[0]=[a('<h1 id="设计趋势-2026-07-09" tabindex="-1">设计趋势 - 2026-07-09 <a class="header-anchor" href="#设计趋势-2026-07-09" aria-label="Permalink to &quot;设计趋势 - 2026-07-09&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于AI与用户体验的融合。主要动态包括面向代理的UX设计原则、AI驱动的用户体验工具如Cursor，以及代理性用户体验对设计认知的改变。最值得关注的是AI如何加速设计流程和提升协作效率，以及AI代理工作流设计模式的探讨。</p><hr><h3 id="_1-面向代理的ux设计" tabindex="-1">1. 面向代理的UX设计 <a class="header-anchor" href="#_1-面向代理的ux设计" aria-label="Permalink to &quot;1. 面向代理的UX设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则指导数字设备中的新型用户体验。</p><p><strong>能解决什么问题</strong>: 解决数字设备中代理系统用户体验设计问题。</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，结合AI技术。</p><p><strong>示例场景</strong>: 智能助手协助用户日常工作和学习。</p><hr><h3 id="_2-ai驱动的用户体验革命-cursor、氛围编码和manus" tabindex="-1">2. AI驱动的用户体验革命：Cursor、氛围编码和Manus <a class="header-anchor" href="#_2-ai驱动的用户体验革命-cursor、氛围编码和manus" aria-label="Permalink to &quot;2. AI驱动的用户体验革命：Cursor、氛围编码和Manus&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs | by Amy Chivavibul | UX Collective</a></p><p><strong>一句话摘要</strong>: Cursor等工具将AI直接嵌入工作流程，实现更自然的交互。</p><p><strong>能解决什么问题</strong>: 解决传统编程工具与AI协作不便的问题。</p><p><strong>产品应用</strong>: 适用于软件开发，通过直接与AI对话提高效率。</p><p><strong>示例场景</strong>: 开发者通过Cursor让代码运行更快。</p><hr><h3 id="_3-代理性用户体验将改变你对设计的所有认知" tabindex="-1">3. 代理性用户体验将改变你对设计的所有认知 <a class="header-anchor" href="#_3-代理性用户体验将改变你对设计的所有认知" aria-label="Permalink to &quot;3. 代理性用户体验将改变你对设计的所有认知&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理性UX设计关注于人机信任的协调，而非界面和功能。</p><p><strong>能解决什么问题</strong>: 如何让用户在AI代理系统中感到被支持、受控且信任。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人类协作的智能系统设计。</p><p><strong>示例场景</strong>: 金融代理标记可疑交易但需人类批准才能冻结账户。</p><hr><h3 id="_4-ai如何改变我的设计工作流程" tabindex="-1">4. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_4-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;4. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI加速设计流程，提高协作效率和迭代速度</p><p><strong>能解决什么问题</strong>: 缩短从设计概念到原型的转换时间，减少无效尝试</p><p><strong>产品应用</strong>: 适用于产品设计领域，通过AI工具快速迭代原型和代码</p><p><strong>示例场景</strong>: 设计师使用Figma和Cursor快速创建可点击原型</p><hr><h3 id="_5-ai代理工作流设计模式概览" tabindex="-1">5. AI代理工作流设计模式概览 <a class="header-anchor" href="#_5-ai代理工作流设计模式概览" aria-label="Permalink to &quot;5. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类为反思型和计划型。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理、规划和执行任务。</p><p><strong>产品应用</strong>: 可应用于开发智能代理，通过工作流模式灵活处理不同问题。</p><p><strong>示例场景</strong>: 使用ReAct和Plan-Solve模式设计智能客服系统。</p><hr><h3 id="_6-人工智能的设计原则" tabindex="-1">6. 人工智能的设计原则 <a class="header-anchor" href="#_6-人工智能的设计原则" aria-label="Permalink to &quot;6. 人工智能的设计原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ui-for-ai/design-principles-for-ai-21b6fac23b04" target="_blank" rel="noreferrer">Design Principles for AI</a></p><p><strong>一句话摘要</strong>: 为AI设计灵活的工作流程、迭代探索、错误检测和多任务处理。</p><p><strong>能解决什么问题</strong>: 提高用户与AI交互的适应性、创造性和效率。</p><p><strong>产品应用</strong>: 适用于需要用户与AI协作的产品，如设计工具、项目管理软件。</p><p><strong>示例场景</strong>: 设计工具通过时间线展示项目进展。</p><hr><h3 id="_7-代理式用户体验-设计智能代理系统的7个原则" tabindex="-1">7. 代理式用户体验：设计智能代理系统的7个原则 <a class="header-anchor" href="#_7-代理式用户体验-设计智能代理系统的7个原则" aria-label="Permalink to &quot;7. 代理式用户体验：设计智能代理系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计智能代理系统时应考虑的上下文共享和跨功能对齐原则。</p><p><strong>能解决什么问题</strong>: 解决智能代理与用户交互时的上下文断裂和信任问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助的任何产品，如客服、自动化助手等。</p><p><strong>示例场景</strong>: 在线客服系统中的智能助手自动回答用户问题。</p><hr><h3 id="_8-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">8. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_8-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;8. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI的信任关系，发挥AI潜力。</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI功能，提升体验。</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板和个性化推荐。</p><p><strong>示例场景</strong>: 智能助手提供个性化建议，展示AI工作原理。</p><hr><h3 id="_9-ai-ux设计模式-人工智能带来的新交互" tabindex="-1">9. AI UX设计模式：人工智能带来的新交互 <a class="header-anchor" href="#_9-ai-ux设计模式-人工智能带来的新交互" aria-label="Permalink to &quot;9. AI UX设计模式：人工智能带来的新交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: AI UX设计模式旨在为AI体验设计提供关键交互模式的参考。</p><p><strong>能解决什么问题</strong>: 解决AI产品界面设计中交互模式选择和应用的问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过评估选择最适合的交互模式。</p><p><strong>示例场景</strong>: 设计一个智能助手，使用文件和文本提示作为参考材料。</p><hr><h3 id="_10-在cursor中使用ai可读设计系统进行设计" tabindex="-1">10. 在Cursor中使用AI可读设计系统进行设计 <a class="header-anchor" href="#_10-在cursor中使用ai可读设计系统进行设计" aria-label="Permalink to &quot;10. 在Cursor中使用AI可读设计系统进行设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/working-with-ai-readable-design-systems-in-cursor-2bba9c9c09d9" target="_blank" rel="noreferrer">Designing with AI-readable design systems in Cursor</a></p><p><strong>一句话摘要</strong>: 利用AI直接从产品需求生成完整产品流程</p><p><strong>能解决什么问题</strong>: 提高设计效率，确保设计遵循统一的设计系统</p><p><strong>产品应用</strong>: 适用于需要快速原型设计的产品设计和开发流程</p><p><strong>示例场景</strong>: 设计师根据产品需求快速生成符合设计系统的原型</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
